"""PDF79 (printed 145–146): future continuous (how to change simple future; examples; activity 1–15); C Future Perfect Tense (definition, explanation, form, examples)."""
from class12_book_common import Book, Builder

BOOK = Book('english')
v = Builder()
v.h('How to change the simple future tense into the future continuous tense:', 'سادہ مستقبل کو مستقبل جاری میں کیسے بدلیں:', 'ساده راتلونکی زمان څنګه په راتلونکي روان زمان بدل کړو:')
for x in [
    ("To express an action that is expected to take place in future and be completed , we use the simple future tense. For example when you have to attend a meeting in the committee room at 11 o'clock tomorrow , you say: I will arrive the committee room at 11 o'clock and will be meeting with the delegates.",
     'کسی ایسے کام کو ظاہر کرنے کے لیے جس کا مستقبل میں ہونا اور مکمل ہونا متوقع ہو، ہم سادہ مستقبل استعمال کرتے ہیں۔ مثلاً جب آپ کو کل 11 بجے کمیٹی روم میں اجلاس میں شرکت کرنی ہو تو آپ کہتے ہیں: I will arrive the committee room at 11 o\'clock and will be meeting with the delegates.',
     'د داسې کار د څرګندولو لپاره چې تمه کېږي په راتلونکي کې ترسره او بشپړ شي، ساده راتلونکی زمان کاروو. د بېلګې په توګه کله چې باید سبا په 11 بجو د کمېټې په کوټه کې په غونډه کې ګډون وکړئ، وایئ: I will arrive the committee room at 11 o\'clock and will be meeting with the delegates.'),
    ("I will arrive the simple future tense of the verb ' to arrive'. It shows that you arrive once; after that you cannot keep on arriving . However, once the action of arriving at the committee room is completed, you may be doing something that goes on continuously, at least for a certain period of time. For that, you will say, 'I will be meeting with the delegates.'",
     "I will arrive فعل ’to arrive‘ کا سادہ مستقبل ہے۔ یہ ظاہر کرتا ہے کہ آپ ایک بار پہنچتے ہیں؛ اس کے بعد آپ مسلسل پہنچتے نہیں رہ سکتے۔ تاہم کمیٹی روم پہنچنے کا عمل مکمل ہونے کے بعد آپ کوئی ایسا کام کر رہے ہو سکتے ہیں جو کم از کم کچھ وقت تک مسلسل جاری رہے۔ اس کے لیے آپ کہیں گے: 'I will be meeting with the delegates.'",
     "I will arrive د 'to arrive' فعل ساده راتلونکی زمان دی. ښيي چې یو ځل رسېږئ؛ وروسته نه شئ کولی چې رسېدو ته دوام ورکړئ. خو کله چې د کمېټې کوټې ته د رسېدو کار بشپړ شي، کېدای شي داسې کار وکړئ چې لږ تر لږه د یوې ټاکلې مودې لپاره دوام ولري. د دې لپاره به وایئ: 'I will be meeting with the delegates.'"),
    ("Will be meeting he future continuous tense of the verb 'to meet'. The construction will+be+present participle (meeting) indicates that the action of meeting will last for a certain duration.",
     "Will be meeting فعل ’to meet‘ کا مستقبل جاری ہے۔ will+be+حال کا اسمِ فاعل (meeting) کی ساخت ظاہر کرتی ہے کہ ملاقات کا عمل کچھ مدت تک جاری رہے گا۔",
     "Will be meeting د 'to meet' فعل راتلونکی روان زمان دی. د will+be+اوسني صفت فاعلي (meeting) جوړښت ښيي چې د لیدنې کار به د یوې ټاکلې مودې لپاره دوام ولري."),
    ('So, you see that the form of a simple future tense is changed to the form of the future continuous tense by putting be + ing form of the verb after shall/will.', 'تو آپ دیکھتے ہیں کہ shall/will کے بعد be + فعل کی ing شکل لگا کر سادہ مستقبل کی شکل مستقبل جاری کی شکل میں بدل جاتی ہے۔', 'نو وینئ چې د shall/will وروسته د be + د فعل ing بڼې په ایښودو د ساده راتلونکي زمان بڼه په راتلونکي روان زمان بدلېږي.'),
    ('Some other examples of the future continuous tense are:', 'مستقبل جاری کی کچھ اور مثالیں یہ ہیں:', 'د راتلونکي روان زمان ځینې نورې بېلګې دا دي:'),
]: v.p(*x)
v.group('list', [('Haris will be doing jogging in the evening.', 'حارث شام کو جاگنگ کر رہا ہو گا۔', 'حارث به ماښام منډې وهي.'), ('Hammad will be watching TV at night.', 'حماد رات کو ٹی وی دیکھ رہا ہو گا۔', 'حماد به شپه ټلویزیون ګوري.'),
                 ('I shall be helping you.', 'میں آپ کی مدد کر رہا ہوں گا۔', 'زه به ستاسو سره مرسته کوم.'), ('She will be washing clothes on Sunday.', 'وہ اتوار کو کپڑے دھو رہی ہو گی۔', 'هغه به د یکشنبې په ورځ جامې مینځي.'),
                 ('Afaq will be earning a lot right after completing his education.', 'آفاق اپنی تعلیم مکمل کرنے کے فوراً بعد بہت کما رہا ہو گا۔', 'افاق به د خپلو زده کړو له بشپړولو سمدستي وروسته ډېرې پیسې ګټي.')])
v.h('Activity', 'سرگرمی', 'فعالیت')
v.p('Put the verbs given in the brackets into the correct form of the future continuous tense:', 'قوسین میں دیے گئے افعال کو مستقبل جاری کی درست شکل میں لکھیں:', 'په قوسونو کې ورکړل شوي فعلونه د راتلونکي روان زمان په سمه بڼه ولیکئ:')
A = ['At this time tomorrow, I ____ (leave).', 'We ____ (have) a party on the last Saturday of the month.', 'I ____ (drive) during rain.', 'He ____ (not take) the bus today.', 'Where ____ (sleep) tonight?',
     "Don't forget your warm clothes. It ____ (snow) by the time you get to Murree.", "Sorry, I can't join you. I ____ (take) my daughter to school at that time.", 'You ____ (feel) thirsty while working in the sun.', 'You ____ (miss) the sunshine in England.',
     'My son ____ (stay) in Saudi Arabia with his uncle .', 'Inanhour,I ____ (sit) in my staff room .', 'Tomorrow at noon, he ____ (work) in his fields.', 'We ____ (have) a dinnertogether.', 'Nextyear, She ____ (appear) in her final exams.', 'This moment, children ____ (play) in the ground.']
