for p in v.paras[-len(A):]: p['untranslatedByDesign'] = True
v.h('C. Future Perfect Tense', 'C. مستقبل مکمل', 'C. راتلونکی بشپړ زمان')
v.p('Defnition: Future perfect tense is used to express an action that is is assumed to be completed later than now ( the time while talking ) and before some other action or a specified point of time in future. When we use this tense, we are projecting ourselves forward into the future and looking back at an action that will be completed sometime later than now.',
    'تعریف: مستقبل مکمل کسی ایسے کام کو ظاہر کرنے کے لیے استعمال ہوتا ہے جس کے بارے میں فرض کیا جائے کہ وہ اب (بات کرنے کے وقت) کے بعد اور مستقبل میں کسی دوسرے کام یا مقررہ وقت سے پہلے مکمل ہو جائے گا۔ اس زمانے کو استعمال کرتے وقت ہم خود کو مستقبل میں آگے لے جاتے ہیں اور ایک ایسے کام کو پیچھے مڑ کر دیکھتے ہیں جو اب کے بعد کسی وقت مکمل ہو گا۔',
    'تعریف: راتلونکی بشپړ زمان د داسې کار د څرګندولو لپاره کارول کېږي چې ګڼل کېږي له اوس (د خبرو له وخت) وروسته او په راتلونکي کې له بل کار یا ټاکلي وخت مخکې بشپړ شي. کله چې دا زمان کاروو، ځانونه راتلونکي ته وړاندې وړو او هغه کار ته شاته ګورو چې له اوس وروسته به یو وخت بشپړ شي.')
v.h('Explanation:', 'وضاحت:', 'تشریح:')
v.p('Consider the example,', 'اس مثال پر غور کریں،', 'دا بېلګه په پام کې ونیسئ،')
v.group('list', [
    ('" Suppose It is 8 a.m by your watch now.The train will leave the station at 9 a.m while, Haris will arrive at the station at 9.15 a.m.', '’’فرض کریں اب آپ کی گھڑی میں صبح کے 8 بجے ہیں۔ ٹرین صبح 9 بجے اسٹیشن سے روانہ ہو گی جبکہ حارث 9:15 بجے اسٹیشن پہنچے گا۔', '"فرض کړئ اوس ستاسو په ساعت سهار 8 بجې دي. اورګاډی به سهار 9 بجې له سټېشن روان شي، په داسې حال کې چې حارث به 9:15 بجې سټېشن ته ورسېږي.'),
    ('So, when Haris arrives at the station, the train will have left."', 'چنانچہ جب حارث اسٹیشن پہنچے گا تو ٹرین جا چکی ہو گی (the train will have left)۔‘‘', 'نو کله چې حارث سټېشن ته ورسېږي، اورګاډی به تللی وي (the train will have left)."'),
    ("'Will have left' indicates that the action of leaving by the train will be complete before the action of arriving of Haris; and both the actions will take place in the future.", "’Will have left‘ ظاہر کرتا ہے کہ ٹرین کے روانہ ہونے کا عمل حارث کے پہنچنے کے عمل سے پہلے مکمل ہو گا؛ اور دونوں عمل مستقبل میں ہوں گے۔", "'Will have left' ښيي چې د اورګاډي د تګ کار به د حارث د رسېدو له کار مخکې بشپړ شي؛ او دواړه کارونه به په راتلونکي کې ترسره شي."),
])
v.p("Note that if two actions take place in the future, the first one is future perfect tense and Second one is simple present tense. Such as 'The teacher will have started the lesson before you reach.'", "نوٹ کریں کہ اگر دو کام مستقبل میں ہوں تو پہلا مستقبل مکمل اور دوسرا سادہ حال میں ہوتا ہے۔ جیسے 'The teacher will have started the lesson before you reach.'", "پام وکړئ چې که دوه کارونه په راتلونکي کې وي، لومړی راتلونکی بشپړ او دویم ساده حال زمان وي. لکه 'The teacher will have started the lesson before you reach.'")
v.h('Form of the future perfect tense', 'مستقبل مکمل کی ساخت', 'د راتلونکي بشپړ زمان جوړښت')
v.p('The form of the future perfect tense is pretty simple. Its structure is subject + auxiliary verb(will)+auxiliary verb (have)+ past participle of the main verb.', 'مستقبل مکمل کی ساخت کافی سادہ ہے۔ اس کی ساخت یہ ہے: فاعل + امدادی فعل (will) + امدادی فعل (have) + اصل فعل کا ماضی کا اسمِ مفعول۔', 'د راتلونکي بشپړ زمان بڼه ډېره ساده ده. جوړښت یې دا دی: فاعل + مرستندوی فعل (will) + مرستندوی فعل (have) + د اصلي فعل تېر صفت مفعولي.')
v.p('Look at these examples:', 'ان مثالوں کو دیکھیں:', 'دې بېلګو ته وګورئ:')
EX = ['He (subject)+will (auxiliary verb)+have(auxiliary verb) +achieved (past participle) his target by the next month.', 'He will have taken admission in the college in 2021 .', 'The match will have ended by the time Salim gets out of bed.', 'I will have left early in the morning before my son gets up.']
v.group('list', [(x,) * 3 for x in EX])
for p in v.paras[-len(EX):]: p['untranslatedByDesign'] = True
